import { Routes } from '@angular/router';
import { unsavedChangesGuard } from '../../shared/utils/unsaved-changes';
import { permissionGuard } from '../../core/auth/permission.guard';
import { ADMIN_PERMS } from '../../core/auth/route-access';
import { opdGuard } from './shared/opd.guard';
import { PHARMACY_VIEW } from './pharmacy/pharmacy-view';

/**
 * EVERY OPD route (OPD dark build), wired ONCE by the foundation. Each carries
 * `opdGuard` — not visible ⇒ bounced to '/' exactly like an unknown URL.
 * FEATURE AGENTS DO NOT EDIT THIS FILE (or app.routes.ts / nav-items.ts / the
 * shell): fill the page component the route already imports, in your folder.
 * Need a new route? Stop and report — the integrator adds it here.
 *
 * Ownership: admin/** → A · frontdesk/**, queue/**, vitals/** → B ·
 * consult/** (+ legacy doctor/**) → C · pharmacy/** → D · home/**, shared/** →
 * foundation (shared contracts: change only with the integrator).
 */
const adminGuard = permissionGuard(ADMIN_PERMS);

/** Children of the signed-in shell (app.routes.ts spreads them). */
export const OPD_SHELL_ROUTES: Routes = [
  // OPD home hub (More → OPD).
  { path: 'opd', canActivate: [opdGuard], loadComponent: () => import('./home/opd-home.component').then(m => m.OpdHomeComponent) },

  // ── Front desk / queue / vitals (Agent B) ──
  { path: 'opd/desk', canActivate: [opdGuard], loadComponent: () => import('./frontdesk/desk.page').then(m => m.OpdDeskPage) },
  { path: 'opd/visit/new', canActivate: [opdGuard], loadComponent: () => import('./frontdesk/book-visit.page').then(m => m.OpdBookVisitPage) },
  { path: 'opd/visit/:id', canActivate: [opdGuard], loadComponent: () => import('./frontdesk/visit-detail.page').then(m => m.OpdVisitDetailPage) },
  { path: 'opd/queue', canActivate: [opdGuard], loadComponent: () => import('./queue/token-queue.page').then(m => m.OpdTokenQueuePage) },
  { path: 'opd/vitals', canActivate: [opdGuard], loadComponent: () => import('./vitals/vitals-station.page').then(m => m.OpdVitalsStationPage) },
  { path: 'opd/vitals/:visitId', canActivate: [opdGuard], loadComponent: () => import('./vitals/vitals-capture.page').then(m => m.OpdVitalsCapturePage) },

  // ── Doctor consult (Agent C) — full-screen via html.pf-opd-immersive ──
  { path: 'opd/consult', canActivate: [opdGuard], loadComponent: () => import('./consult/my-patients.page').then(m => m.OpdMyPatientsPage) },
  { path: 'opd/consult/:visitId', canActivate: [opdGuard], data: { recreateOn: ['visitId'] },
    loadComponent: () => import('./consult/consult-workspace.page').then(m => m.OpdConsultWorkspacePage) },
  { path: 'opd/patient/:patientId', canActivate: [opdGuard], loadComponent: () => import('./consult/patient-history.page').then(m => m.OpdPatientHistoryPage) },

  // ── Pharmacy (Agent D) ──
  { path: 'opd/pharmacy', canActivate: [opdGuard], loadComponent: () => import('./pharmacy/rx-queue.page').then(m => m.PharmacyRxQueuePage) },
  { path: 'opd/pharmacy/dispense/:visitId', canActivate: [opdGuard], loadComponent: () => import('./pharmacy/dispense.page').then(m => m.PharmacyDispensePage) },
  { path: 'opd/pharmacy/counter', canActivate: [opdGuard], loadComponent: () => import('./pharmacy/walk-in-counter.page').then(m => m.PharmacyWalkInCounterPage) },
  { path: 'opd/pharmacy/stock', canActivate: [opdGuard], loadComponent: () => import('./pharmacy/stock.page').then(m => m.PharmacyStockPage) },
  { path: 'opd/pharmacy/suppliers', canActivate: [opdGuard], loadComponent: () => import('./pharmacy/suppliers.page').then(m => m.PharmacySuppliersPage) },
  { path: 'opd/pharmacy/purchase-orders', canActivate: [opdGuard], loadComponent: () => import('./pharmacy/purchase-orders.page').then(m => m.PharmacyPurchaseOrdersPage) },
  { path: 'opd/pharmacy/returns', canActivate: [opdGuard], loadComponent: () => import('./pharmacy/returns.page').then(m => m.PharmacyReturnsPage) },
  { path: 'opd/pharmacy/h1-register', canActivate: [opdGuard], loadComponent: () => import('./pharmacy/h1-register.page').then(m => m.PharmacyH1RegisterPage) },

  // ── Legacy OPD screens (pre-dark build) — kept, now gated. Agent C (doctor
  //    queue / consult room) and Agent B (desk consult page) retire them. ──
  { path: 'doctor', canActivate: [opdGuard], loadComponent: () => import('./doctor/doctor-queue.component').then(m => m.DoctorQueueComponent) },
  { path: 'doctor/consult/:id', canActivate: [opdGuard], loadComponent: () => import('./doctor/consult-room.component').then(m => m.ConsultRoomComponent) },
];

/**
 * OPD admin (adminGuard + opdGuard). Agent A, except pharmacy settings (D). The Settings shell hosts every one of
 * these except the full-screen editors (service editor, form builder): see features/admin/settings/settings.routes.ts.
 * `/admin/opd` itself (the old OPD hub) redirects to the overview's OPD section.
 */
export const OPD_ADMIN_ROUTES: Routes = [
  { path: 'admin/opd/departments', canActivate: [adminGuard, opdGuard], loadComponent: () => import('./admin/departments.page').then(m => m.OpdDepartmentsPage) },
  { path: 'admin/opd/services/:id', canActivate: [adminGuard, opdGuard], loadComponent: () => import('./admin/service-editor.page').then(m => m.OpdServiceEditorPage) },
  // OPD → Doctors: per-doctor consultation-fee grid (existing).
  { path: 'admin/opd/doctors', canActivate: [adminGuard, opdGuard], loadComponent: () => import('./admin/doctors-admin.component').then(m => m.DoctorsAdminComponent) },
  { path: 'admin/opd/forms', canActivate: [adminGuard, opdGuard], loadComponent: () => import('./admin/form-library.page').then(m => m.OpdFormLibraryPage) },
  { path: 'admin/opd/forms/:id', canActivate: [adminGuard, opdGuard], loadComponent: () => import('./admin/form-builder.page').then(m => m.OpdFormBuilderPage) },
  { path: 'admin/opd/workflow', canActivate: [adminGuard, opdGuard], loadComponent: () => import('./admin/workflow.page').then(m => m.OpdWorkflowPage) },
  // OPD → Settings: the follow-up policy (existing).
  { path: 'admin/opd/settings', canActivate: [adminGuard, opdGuard], loadComponent: () => import('./admin/opd-settings.component').then(m => m.OpdSettingsComponent) },
  // Pharmacy is its own department in Settings (Settings re-home 2026-11-17): its real settings and the drug master,
  // ONE page pinned to a view by PHARMACY_VIEW (the Settings left panel is the switch). Old /admin/opd/pharmacy and
  // /admin/opd/drugs redirect here through settings-map's rehome().
  { path: 'admin/pharmacy/drugs', canActivate: [adminGuard, opdGuard], data: { moduleId: 'pharmacy', [PHARMACY_VIEW]: 'drugs' },
    loadComponent: () => import('./pharmacy/pharmacy-settings.page').then(m => m.PharmacySettingsPage) },
  { path: 'admin/pharmacy', canActivate: [adminGuard, opdGuard], data: { moduleId: 'pharmacy', [PHARMACY_VIEW]: 'settings' },
    loadComponent: () => import('./pharmacy/pharmacy-settings.page').then(m => m.PharmacySettingsPage) },
  // Order IDs per module (2026-11-18): OPD's visit number and Pharmacy's dispense number formats.
  { path: 'admin/opd/numbers', canActivate: [adminGuard, opdGuard], canDeactivate: [unsavedChangesGuard], loadComponent: () => import('./admin/opd-numbers.page').then(m => m.OpdNumbersPage) },
  { path: 'admin/pharmacy/numbers', canActivate: [adminGuard, opdGuard], canDeactivate: [unsavedChangesGuard], data: { moduleId: 'pharmacy' },
    loadComponent: () => import('./pharmacy/pharmacy-numbers.page').then(m => m.PharmacyNumbersPage) },
  // OPD front desk, alerts and numbers (`?tab=` = OPD_FRONT_DESK_SECTIONS): appointments and booking, the shared
  // referring list, OPD alerts. Numbers on OPD screens waits for OPD screens in the KPI-card list.
  { path: 'admin/opd/front-desk', canActivate: [adminGuard, opdGuard], canDeactivate: [unsavedChangesGuard], loadComponent: () => import('./admin/front-desk.page').then(m => m.OpdFrontDeskPage) },
];

/** The legacy desk consult page under /frontdesk (child of the frontdesk area). */
export const OPD_FRONTDESK_CHILD_ROUTES: Routes = [
  { path: 'consult', canActivate: [opdGuard], loadComponent: () => import('./consult-page/consult-page.component').then(m => m.ConsultPageComponent) },
];
